  --vol-1:#2a2a2d; --vol-2:#141416; --vol-3:#050506; --vol-cap:#1b1b1d; --vol-dot:#e6e0cf;
  --bezel-1:#2a2a2d; --bezel-2:#141416; --bezel-3:#050506;
  --plate-1:#b0281f; --plate-2:#8f1d16; --plate-3:#5c120d; --key-1:#2f2f33; --key-2:#151517; --key-hover-1:#3a3a3f; --key-hover-2:#1c1c1f;
  --title-1:#1d1d20; --title-2:#0b0b0c;
}html[data-skin="mulchmaster"] body:not(.pop){background:#4d7a2a repeating-linear-gradient(90deg,rgba(255,255,255,.07) 0 90px,rgba(0,0,0,.07) 90px 180px);padding:clamp(96px,10vw,132px) clamp(18px,10.5vw,112px) 34px clamp(18px,7.4vw,80px)}html[data-skin="mulchmaster"] .wrap.wrap{max-width:1180px;background:url("data:image/webp;base64,") 0 0/512px 512px,#a31f17;border:3px solid #3e0a06;border-radius:34px 34px 46% 46%/34px 34px 170px 170px;
  padding:16px clamp(10px,1.8vw,20px) 46px;gap:16px;box-shadow:0 22px 44px rgba(0,0,0,.55),0 5px 12px rgba(0,0,0,.45),inset 0 2px 0 rgba(255,170,150,.35),inset 0 0 0 5px rgba(0,0,0,.18),inset 0 -40px 70px rgba(30,0,0,.45);position:relative}html[data-skin="mulchmaster"] .top .deck,html[data-skin="mulchmaster"] .sheet,html[data-skin="mulchmaster"] .pop,html[data-skin="mulchmaster"] .syncbar,html[data-skin="mulchmaster"] .ahead,html[data-skin="mulchmaster"] .bellpanel{background:radial-gradient(circle at 14px 14px,#9a9aa0 0 3px,#3a3a3e 4px,transparent 6px),radial-gradient(circle at calc(100% - 14px) 14px,#9a9aa0 0 3px,#3a3a3e 4px,transparent 6px),
